  msg_world: 'દુનિયા બદલાઈ. રોબોટનું શીખેલું રહે છે, અને શોધખોળ ફરી ε = {e} થઈ. વધુ શીખવો અને જુઓ તે કેવી રીતે અનુકૂળ થાય છે.',
