  upd_title: 'છેલ્લો અપડેટ: Q-લર્નિંગનો નિયમ',
  upd_rule: 'નવો Q = જૂનો Q + α × (ઇનામ + γ × આગલા ખાનાનો સૌથી સારો Q − જૂનો Q)',
