  upd_result: 'એટલે ત્યાંથી {act} જવાની Q-કિંમત {old} થી બદલાઈને {new} થઈ.',
  learn_title: 'અંદર શું થાય છે?',
  l1_t: 'એજન્ટ',
  l1: 'શીખનાર, જે નિર્ણય લે છે. અહીં તે રોબોટ છે. વીડિયો ગેમમાં તે કમ્પ્યુટરનો ખેલાડી હોત.',
  l2_t: 'પર્યાવરણ',
  l2: 'એજન્ટની આસપાસનું બધું: દીવાલો, ખાડા અને ખજાનાવાળી 7 × 7 ગ્રિડ. દરેક ચાલ પછી તે રોબોટને કહે છે કે તે હવે ક્યાં છે અને તેને કેટલું ઇનામ મળ્યું.',
  l3_t: 'સ્થિતિ (સ્ટેટ)',
  l3: 'અત્યારની હાલત. અહીં સ્થિતિ એટલે ફક્ત રોબોટનું ખાનું, એટલે 49 સ્થિતિઓ છે.',
  l4_t: 'ક્રિયા (ઍક્શન)',
  l4: 'એજન્ટ જે પસંદ કરી શકે: ઉપર, જમણે, નીચે કે ડાબે. દીવાલ કે કિનારા તરફ જતાં રોબોટ ત્યાં જ રહે છે.',
  l5_t: 'ઇનામ (રિવૉર્ડ)',
  l5: 'સારું કે ખરાબ કહેતી એક સંખ્યા: ખજાને +10, ખાડે −10 અને દરેક પગલે થોડો માઇનસ. રોબોટને કોઈ રસ્તો કહેતું નથી. તેને ફક્ત ઇનામ મળે છે.',
  l6_t: 'Q-કિંમત અને Q-ટેબલ',
  l6: 'Q(સ્થિતિ, ક્રિયા) એ રોબોટનો અંદાજ છે કે ત્યાં તે ક્રિયા કરવાથી આગળ કુલ કેટલું ઇનામ મળશે. બધા 49 × 4 અંદાજ મળીને Q-ટેબલ બને છે. દરેક પગલા પછી Q-લર્નિંગના નિયમથી એક અંદાજ સુધરે છે.',
  l7_t: 'શોધખોળ કે લાભ?',
  l7: 'લાભ = જાણીતી સૌથી સારી ચાલ જ ચાલો. શોધખોળ = કંઈક રૅન્ડમ અજમાવો, કદાચ તેનાથી પણ સારું મળે. જેમ કેન્ટીનમાં હંમેશાં મનપસંદ સમોસા લેવા, કે કોઈ નવી વાનગી ચાખવી. રોબોટ કેટલી વાર શોધખોળ કરે તે ε નક્કી કરે છે.',
  l8_t: 'α અને γ',
  l8: 'α (શીખવાનો દર) કહે છે કે અંદાજ કેટલા જલદી બદલાય છે. γ (ડિસ્કાઉન્ટ) કહે છે કે ભવિષ્ય કેટલું મહત્ત્વનું છે: આજના ₹100 આવતા વર્ષે વચન આપેલા ₹100 કરતાં વધુ કીમતી છે, અને નજીકનો ખજાનો દૂરના કરતાં સારો.',
  l9_t: 'ગેમ અને રોબોટ કેવી રીતે શીખે છે',
