  l1: 'ਸਿੱਖਣ ਵਾਲਾ, ਜੋ ਫ਼ੈਸਲੇ ਲੈਂਦਾ ਹੈ। ਇੱਥੇ ਉਹ ਰੋਬੋਟ ਹੈ। ਵੀਡੀਓ ਗੇਮ ਵਿੱਚ ਉਹ ਕੰਪਿਊਟਰ ਵਾਲਾ ਖਿਡਾਰੀ ਹੁੰਦਾ।',
  l2_t: 'ਵਾਤਾਵਰਣ',
  l2: 'ਏਜੰਟ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਸਭ ਕੁਝ: ਕੰਧਾਂ, ਟੋਇਆਂ ਅਤੇ ਖ਼ਜ਼ਾਨੇ ਵਾਲੀ 7 × 7 ਗ੍ਰਿਡ। ਹਰ ਚਾਲ ਤੋਂ ਬਾਅਦ ਇਹ ਰੋਬੋਟ ਨੂੰ ਦੱਸਦਾ ਹੈ ਕਿ ਉਹ ਹੁਣ ਕਿੱਥੇ ਹੈ ਅਤੇ ਉਸਨੂੰ ਕਿੰਨਾ ਇਨਾਮ ਮਿਲਿਆ।',
