  l3: 'ਹੁਣ ਦੀ ਹਾਲਤ। ਇੱਥੇ ਸਥਿਤੀ ਬੱਸ ਰੋਬੋਟ ਦਾ ਖ਼ਾਨਾ ਹੈ, ਇਸ ਲਈ 49 ਸਥਿਤੀਆਂ ਹਨ।',
  l4_t: 'ਕਿਰਿਆ (ਐਕਸ਼ਨ)',
  l4: 'ਏਜੰਟ ਜੋ ਚੁਣ ਸਕਦਾ ਹੈ: ਉੱਪਰ, ਸੱਜੇ, ਹੇਠਾਂ ਜਾਂ ਖੱਬੇ। ਕੰਧ ਜਾਂ ਕਿਨਾਰੇ ਵੱਲ ਜਾਣ ਤੇ ਰੋਬੋਟ ਉੱਥੇ ਹੀ ਰਹਿੰਦਾ ਹੈ।',
  l5_t: 'ਇਨਾਮ (ਰਿਵਾਰਡ)',
  l5: 'ਇੱਕ ਅੰਕ ਜੋ ਚੰਗਾ ਜਾਂ ਮਾੜਾ ਦੱਸਦਾ ਹੈ: ਖ਼ਜ਼ਾਨੇ ਤੇ +10, ਟੋਏ ਤੇ −10 ਅਤੇ ਹਰ ਕਦਮ ਤੇ ਥੋੜ੍ਹਾ ਮਾਇਨਸ। ਰੋਬੋਟ ਨੂੰ ਕੋਈ ਰਾਹ ਨਹੀਂ ਦੱਸਦਾ। ਉਸਨੂੰ ਸਿਰਫ਼ ਇਨਾਮ ਮਿਲਦੇ ਹਨ।',
  l6_t: 'Q-ਵੈਲਿਊ ਅਤੇ Q-ਟੇਬਲ',
  l6: 'Q(ਸਥਿਤੀ, ਕਿਰਿਆ) ਰੋਬੋਟ ਦਾ ਅੰਦਾਜ਼ਾ ਹੈ ਕਿ ਉੱਥੇ ਉਹ ਕਿਰਿਆ ਕਰਨ ਤੇ ਅੱਗੇ ਕੁੱਲ ਕਿੰਨਾ ਇਨਾਮ ਮਿਲੇਗਾ। ਸਾਰੇ 49 × 4 ਅੰਦਾਜ਼ੇ ਮਿਲ ਕੇ Q-ਟੇਬਲ ਬਣਾਉਂਦੇ ਹਨ। ਹਰ ਕਦਮ ਤੋਂ ਬਾਅਦ Q-ਲਰਨਿੰਗ ਦੇ ਨਿਯਮ ਨਾਲ ਇੱਕ ਅੰਦਾਜ਼ਾ ਸੁਧਰਦਾ ਹੈ।',
  l7_t: 'ਖੋਜ ਜਾਂ ਫ਼ਾਇਦਾ?',
  l7: 'ਫ਼ਾਇਦਾ = ਜੋ ਸਭ ਤੋਂ ਵਧੀਆ ਚਾਲ ਪਤਾ ਹੈ, ਉਹੀ ਚੱਲੋ। ਖੋਜ = ਕੁਝ ਰੈਂਡਮ ਅਜ਼ਮਾਓ, ਸ਼ਾਇਦ ਉਸ ਤੋਂ ਵੀ ਵਧੀਆ ਮਿਲ ਜਾਵੇ। ਜਿਵੇਂ ਕੰਟੀਨ ਵਿੱਚ ਹਮੇਸ਼ਾ ਆਪਣਾ ਮਨਪਸੰਦ ਸਮੋਸਾ ਲੈਣਾ, ਜਾਂ ਕੋਈ ਨਵੀਂ ਡਿਸ਼ ਚੱਖਣੀ। ε ਤੈਅ ਕਰਦਾ ਹੈ ਕਿ ਰੋਬੋਟ ਕਿੰਨੀ ਵਾਰ ਖੋਜ ਕਰੇ।',
