  l9_t: 'ਗੇਮਾਂ ਅਤੇ ਰੋਬੋਟ ਕਿਵੇਂ ਸਿੱਖਦੇ ਹਨ',
  l9: 'AlphaGo ਨੇ ਕੁਝ ਹੱਦ ਤੱਕ ਆਪਣੇ ਆਪ ਨਾਲ ਲੱਖਾਂ ਬਾਜ਼ੀਆਂ ਖੇਡ ਕੇ Go ਸਿੱਖਿਆ, ਅਤੇ 2016 ਵਿੱਚ ਦੁਨੀਆ ਦੇ ਸਭ ਤੋਂ ਵਧੀਆ ਖਿਡਾਰੀਆਂ ਵਿੱਚੋਂ ਇੱਕ, ਲੀ ਸੇਡੋਲ ਨੂੰ ਹਰਾਇਆ। ਰੋਬੋਟ ਸਿਮੂਲੇਸ਼ਨ ਵਿੱਚ ਤੁਰਨਾ ਸਿੱਖਦੇ ਹਨ, ਅਤੇ ਚੈਟਬੋਟ ਇਨਸਾਨਾਂ ਦੀ ਰਾਏ ਨਾਲ ਸੁਧਾਰੇ ਜਾਂਦੇ ਹਨ (RLHF)। ਵੱਡੀਆਂ ਸਮੱਸਿਆਵਾਂ ਵਿੱਚ ਸਥਿਤੀਆਂ ਇੰਨੀਆਂ ਹੁੰਦੀਆਂ ਹਨ ਕਿ ਟੇਬਲ ਕੰਮ ਨਹੀਂ ਕਰਦੀ, ਇਸ ਲਈ ਨਿਊਰਲ ਨੈੱਟਵਰਕ ਅੰਦਾਜ਼ੇ ਲਾਉਂਦਾ ਹੈ (Deep Q-Network)।',
