  msg_end_timeout: 'ఎపిసోడ్ {n} ముగిసింది: {s} అడుగుల్లోనూ నిధి దొరకలేదు, అందుకే రోబో ఆగిపోయింది. మొత్తం బహుమతి {r}.',
  msg_fast: '{n} ఎపిసోడ్‌లు నేర్పించాం: నిధి {g} సార్లు, గుంత {p} సార్లు, మధ్యలో ఆగింది {t} సార్లు.',
  msg_playing: 'నేర్చుకున్న విధానం నడుస్తోంది: ఎప్పుడూ ఉత్తమ కదలిక, అన్వేషణ లేదు, కొత్తగా నేర్చుకోవడం లేదు.',
