  msg_play_lost: 'నేర్చుకున్న విధానం: రోబో గుండ్రంగా తిరుగుతోంది, నిధిని చేరడం లేదు. ఇంకా నేర్పించండి.',
  msg_stopped: 'ఆపబడింది.',
