  msg_unreachable: 'రోబో తన ప్రారంభం నుంచి ఏ నిధినీ చేరలేదు. కొన్ని గోడలు లేదా గుంతలు తీసేయండి.',
  msg_world: 'ప్రపంచం మారింది. రోబో నేర్చుకున్నది అలాగే ఉంటుంది, అన్వేషణ మళ్లీ ε = {e} అయ్యింది. ఇంకా నేర్పించి అది ఎలా అలవాటు పడుతుందో చూడండి.',
  msg_reset: 'నేర్పు రీసెట్ అయింది: ప్రతి Q-విలువ మళ్లీ 0.',
  msg_start_cell: 'ఇది రోబో ప్రారంభ గడి. దీన్ని కదపడానికి “ప్రారంభం మార్చు” ఎంచుకోండి.',
  msg_preset: '“{name}” ప్రపంచం లోడ్ అయింది. రోబో సున్నా నుంచి నేర్చుకోవడం మొదలుపెడుతుంది.',
  world_title: 'ప్రపంచం',
  preset_label: 'సిద్ధంగా ఉన్న ప్రపంచాలు',
  preset_simple: 'సులభం',
  preset_maze: 'చిక్కుదారి',
  preset_cliff: 'లోయ అంచు',
