  hint_simple: 'కొన్ని గోడలు, గుంతలు. మొదలుపెట్టడానికి మంచి ప్రపంచం.',
  hint_maze: 'పొడవైన, వంకర దారి. ఒక అడ్డదారి గుంతలో ముగుస్తుంది!',
  hint_cliff: 'కింది వరుస నిండా గుంతలే. అతి చిన్న దారి అంచుకు ఆనుకుని వెళ్తుంది.',
  hint_empty: 'గోడలు లేవు, గుంతలు లేవు. విలువలు నిధి నుంచి చుట్టూ ఎలా వ్యాపిస్తాయో చూడండి.',
  hint_custom: 'మీ సొంత ప్రపంచం. గడులపై తట్టి మార్చండి.',
  tool_label: 'గడిపై తడితే',
  tool_cycle: 'మార్చు',
