  hint_cycle: 'ప్రతి తట్టుకు: ఖాళీ → గోడ → గుంత → నిధి → ఖాళీ. చాలా గడుల కోసం వేలు లాగండి.',
  hint_start: 'మీరు తట్టిన గడి నుంచే రోబో మొదలుపెడుతుంది.',
  hint_look: 'ఏదైనా గడిపై తట్టి, “రోబో మెదడు లోపల”లో దాని 4 Q-విలువలు చూడండి.',
  legend_robot: 'రోబో (ఏజెంట్)',
  legend_goal: 'నిధి +10',
  legend_pit: 'గుంత −10',
  legend_wall: 'గోడ',
  legend_start: 'ప్రారంభం',
  settings_title: 'నేర్చుకునే సెట్టింగ్‌లు',
  alpha_label: 'నేర్చుకునే రేటు α',
  alpha_hint: 'ఒక కొత్త అనుభవం పాత అంచనాను ఎంత మారుస్తుంది. 1 = కొత్తదాన్నే నమ్ము, చిన్నది = నెమ్మదిగా నేర్చుకోవడం.',
  gamma_label: 'డిస్కౌంట్ γ',
  gamma_hint: 'భవిష్యత్తు బహుమతులు ఎంత ముఖ్యం. 1 దగ్గర = దూరం వరకు ప్రణాళిక, 0 = తర్వాతి బహుమతి గురించే.',
  eps_label: 'అన్వేషణ ε',
  eps_hint: 'యాదృచ్ఛిక కదలికకు అవకాశం. యాదృచ్ఛిక కదలికలు కొత్త దారులు కనుగొంటాయి; ఉత్తమ కదలికలు తెలిసినదాన్ని వాడుకుంటాయి.',
  decay_label: 'కాలంతో పాటు తక్కువ అన్వేషణ (ప్రతి ఎపిసోడ్ తర్వాత ε × 0.99)',
  cost_label: 'ప్రతి అడుగుకు శిక్ష',
  cost_hint: 'ప్రతి సాధారణ అడుగుకు ఈ బహుమతి (చిన్న మైనస్) వస్తుంది. దీనివల్ల రోబో త్వరపడుతుంది.',
  defaults_btn: 'డిఫాల్ట్ సెట్టింగ్‌లు',
