  chart_x: 'ఎపిసోడ్',
  chart_y: 'మొత్తం బహుమతి',
  chart_raw: 'ప్రతి ఎపిసోడ్',
  chart_avg: 'చివరి 20 సగటు',
  chart_best: 'సాధ్యమైన ఉత్తమం',
  chart_empty: 'రోబోకు నేర్పించండి, దాని బహుమతులు ఇక్కడ కనిపిస్తాయి.',
  chart_note: 'మొదట గీత కిందగా, ఎగుడుదిగుడుగా ఉంటుంది: రోబో అన్వేషిస్తూ గుంతల్లో పడుతుంది. అది నేర్చుకునే కొద్దీ గీత సాధ్యమైన ఉత్తమ బహుమతి వైపు ఎక్కుతుంది.',
