  l2_t: 'ಪರಿಸರ',
  l2: 'ಏಜೆಂಟ್‌ನ ಸುತ್ತಲಿನ ಎಲ್ಲವೂ: ಗೋಡೆ, ಗುಂಡಿ ಮತ್ತು ನಿಧಿ ಇರುವ 7 × 7 ಚೌಕಗಳು. ಪ್ರತಿ ಚಲನೆಯ ನಂತರ ರೋಬೋಟ್ ಈಗ ಎಲ್ಲಿದೆ, ಎಷ್ಟು ಬಹುಮಾನ ಸಿಕ್ಕಿತು ಎಂದು ಇದು ಹೇಳುತ್ತದೆ.',
  l3_t: 'ಸ್ಥಿತಿ (ಸ್ಟೇಟ್)',
  l3: 'ಈಗಿನ ಪರಿಸ್ಥಿತಿ. ಇಲ್ಲಿ ಸ್ಥಿತಿ ಎಂದರೆ ರೋಬೋಟ್ ಇರುವ ಚೌಕ ಮಾತ್ರ, ಆದ್ದರಿಂದ 49 ಸ್ಥಿತಿಗಳು.',
