  l4: 'ಏಜೆಂಟ್ ಆಯ್ಕೆಮಾಡಬಹುದಾದದ್ದು: ಮೇಲೆ, ಬಲಕ್ಕೆ, ಕೆಳಗೆ ಅಥವಾ ಎಡಕ್ಕೆ. ಗೋಡೆ ಅಥವಾ ಅಂಚಿನ ಕಡೆ ಹೋದರೆ ರೋಬೋಟ್ ಅಲ್ಲೇ ಇರುತ್ತದೆ.',
  l5_t: 'ಬಹುಮಾನ',
  l5: 'ಒಳ್ಳೆಯದೋ ಕೆಟ್ಟದೋ ಹೇಳುವ ಒಂದು ಸಂಖ್ಯೆ: ನಿಧಿಗೆ +10, ಗುಂಡಿಗೆ −10, ಪ್ರತಿ ಹೆಜ್ಜೆಗೆ ಸ್ವಲ್ಪ ಮೈನಸ್. ಯಾರೂ ರೋಬೋಟ್‌ಗೆ ದಾರಿ ಹೇಳುವುದಿಲ್ಲ. ಅದಕ್ಕೆ ಬಹುಮಾನಗಳು ಮಾತ್ರ ಸಿಗುತ್ತವೆ.',
  l6_t: 'Q-ಮೌಲ್ಯ ಮತ್ತು Q-ಕೋಷ್ಟಕ',
  l6: 'Q(ಸ್ಥಿತಿ, ಕ್ರಿಯೆ) ಎಂದರೆ ಅಲ್ಲಿ ಆ ಕ್ರಿಯೆ ಮಾಡಿದರೆ ಮುಂದೆ ಒಟ್ಟು ಎಷ್ಟು ಬಹುಮಾನ ಸಿಗಬಹುದು ಎಂಬ ರೋಬೋಟ್‌ನ ಅಂದಾಜು. ಎಲ್ಲ 49 × 4 ಅಂದಾಜುಗಳು ಸೇರಿ Q-ಕೋಷ್ಟಕ. ಪ್ರತಿ ಹೆಜ್ಜೆಯ ನಂತರ Q-ಲರ್ನಿಂಗ್ ನಿಯಮದಿಂದ ಒಂದು ಅಂದಾಜು ಸುಧಾರಿಸುತ್ತದೆ.',
  l7_t: 'ಅನ್ವೇಷಣೆಯೋ, ಬಳಕೆಯೋ?',
  l7: 'ಬಳಕೆ = ಗೊತ್ತಿರುವ ಅತ್ಯುತ್ತಮ ಚಲನೆಯನ್ನೇ ಮಾಡು. ಅನ್ವೇಷಣೆ = ಯಾದೃಚ್ಛಿಕವಾಗಿ ಏನಾದರೂ ಪ್ರಯತ್ನಿಸು, ಇನ್ನೂ ಒಳ್ಳೆಯದು ಸಿಗಬಹುದು. ಕ್ಯಾಂಟೀನ್‌ನಲ್ಲಿ ಯಾವಾಗಲೂ ಇಷ್ಟದ ಸಮೋಸ ತೆಗೆದುಕೊಳ್ಳುವುದು, ಅಥವಾ ಹೊಸ ತಿನಿಸು ರುಚಿ ನೋಡುವುದು ಹಾಗೆ. ರೋಬೋಟ್ ಎಷ್ಟು ಬಾರಿ ಅನ್ವೇಷಿಸಬೇಕು ಎಂದು ε ನಿರ್ಧರಿಸುತ್ತದೆ.',
