  l8: 'α (ಕಲಿಕೆಯ ದರ) ಅಂದಾಜುಗಳು ಎಷ್ಟು ಬೇಗ ಬದಲಾಗುತ್ತವೆ ಎಂದು ಹೇಳುತ್ತದೆ. γ (ಡಿಸ್ಕೌಂಟ್) ಭವಿಷ್ಯ ಎಷ್ಟು ಮುಖ್ಯ ಎಂದು ಹೇಳುತ್ತದೆ: ಇಂದಿನ ₹100, ಮುಂದಿನ ವರ್ಷ ಕೊಡುವೆನೆಂದ ₹100 ಗಿಂತ ಹೆಚ್ಚು ಬೆಲೆಯದು; ಹತ್ತಿರದ ನಿಧಿ ದೂರದ್ದಕ್ಕಿಂತ ಒಳ್ಳೆಯದು.',
