  l9: 'AlphaGo ಸ್ವಲ್ಪಮಟ್ಟಿಗೆ ತನ್ನೊಂದಿಗೇ ಲಕ್ಷಾಂತರ ಆಟಗಳನ್ನು ಆಡಿ Go ಕಲಿಯಿತು, 2016 ರಲ್ಲಿ ವಿಶ್ವದ ಅತ್ಯುತ್ತಮ ಆಟಗಾರರಲ್ಲಿ ಒಬ್ಬರಾದ ಲೀ ಸೆಡೋಲ್ ಅವರನ್ನು ಸೋಲಿಸಿತು. ರೋಬೋಟ್‌ಗಳು ಸಿಮ್ಯುಲೇಶನ್‌ನಲ್ಲಿ ನಡೆಯಲು ಕಲಿಯುತ್ತವೆ, ಚಾಟ್‌ಬಾಟ್‌ಗಳನ್ನು ಮನುಷ್ಯರ ಅಭಿಪ್ರಾಯದಿಂದ ಸುಧಾರಿಸಲಾಗುತ್ತದೆ (RLHF). ದೊಡ್ಡ ಸಮಸ್ಯೆಗಳಲ್ಲಿ ಸ್ಥಿತಿಗಳು ತುಂಬಾ ಹೆಚ್ಚು, ಕೋಷ್ಟಕ ಸಾಲದು, ಆದ್ದರಿಂದ ನ್ಯೂರಲ್ ನೆಟ್‌ವರ್ಕ್ ಅಂದಾಜು ಮಾಡುತ್ತದೆ (Deep Q-Network).',
