  tip3: '“ನಾಲ್ಕೂ Q-ಮೌಲ್ಯಗಳು” ಆನ್ ಮಾಡಿ, “ಒಳಗೆ ನೋಡಿ” ಮೂಲಕ ಸಂಖ್ಯೆಗಳನ್ನು ಓದಿ. ಬಾಣ ಯಾವಾಗಲೂ ನಾಲ್ಕರಲ್ಲಿ ಅತಿ ದೊಡ್ಡ ಮೌಲ್ಯದ ಕಡೆಗೇ ಇರುತ್ತದೆ.',
