  msg_back: 'വീണ്ടും സ്വാഗതം! റോബോട്ടിന് {n} എപ്പിസോഡിലെ പഠനം ഓർമ്മയുണ്ട്.',
  msg_explore: '🎲 പര്യവേക്ഷണം: ക്രമരഹിത നീക്കം {act}.',
  msg_exploit: '🧠 പ്രയോജനപ്പെടുത്തൽ: അറിയാവുന്ന ഏറ്റവും നല്ല നീക്കം {act}.',
  msg_bump: 'ഇടി! ചുവരോ അരികോ ആയിരുന്നു, അതിനാൽ അവിടെത്തന്നെ നിന്നു.',
  msg_goal: 'നിധി കിട്ടി: +10!',
  msg_pit: 'കുഴിയിൽ വീണു: −10!',
  msg_reward: 'സമ്മാനം {r}.',
  msg_end_goal: 'എപ്പിസോഡ് {n} കഴിഞ്ഞു: {s} ചുവടിൽ നിധി കിട്ടി. ആകെ സമ്മാനം {r}.',
  msg_end_pit: 'എപ്പിസോഡ് {n} കഴിഞ്ഞു: {s} ചുവടിനു ശേഷം കുഴിയിൽ വീണു. ആകെ സമ്മാനം {r}.',
  msg_end_timeout: 'എപ്പിസോഡ് {n} കഴിഞ്ഞു: {s} ചുവടിലും നിധി കിട്ടിയില്ല, അതിനാൽ റോബോട്ട് നിർത്തി. ആകെ സമ്മാനം {r}.',
  msg_fast: '{n} എപ്പിസോഡ് പഠിപ്പിച്ചു: നിധി {g} തവണ, കുഴി {p} തവണ, പാതിവഴിയിൽ നിർത്തി {t} തവണ.',
  msg_playing: 'പഠിച്ച നയം ഓടുന്നു: എപ്പോഴും ഏറ്റവും നല്ല നീക്കം, പര്യവേക്ഷണമില്ല, പുതിയ പഠനമില്ല.',
  msg_play_goal: 'പഠിച്ച നയം: {s} ചുവടിൽ നിധിയിലെത്തി (ഏറ്റവും ചെറിയ വഴി: {best}).',
  msg_play_best: 'ഇതാണ് ഏറ്റവും ചെറിയ സുരക്ഷിത വഴി! 🎉',
  msg_play_pit: 'പഠിച്ച നയം: റോബോട്ട് കുഴിയിലേക്ക് പോയി. അതിന് ഇനിയും പരിശീലനം വേണം.',
  msg_play_lost: 'പഠിച്ച നയം: റോബോട്ട് വട്ടം കറങ്ങുന്നു, നിധിയിൽ എത്തുന്നില്ല. ഇനിയും പഠിപ്പിക്കൂ.',
  msg_stopped: 'നിർത്തി.',
  msg_no_goal: 'റോബോട്ടിന് തിരയാൻ എന്തെങ്കിലും ഉണ്ടാകാൻ കളങ്ങളിൽ കുറഞ്ഞത് ഒരു നിധി വയ്ക്കുക.',
  msg_unreachable: 'റോബോട്ടിന് തുടക്കത്തിൽ നിന്ന് ഒരു നിധിയിലും എത്താനാവില്ല. കുറച്ച് ചുവരുകളോ കുഴികളോ മാറ്റുക.',
  msg_world: 'ലോകം മാറി. റോബോട്ട് പഠിച്ചത് നിലനിൽക്കും, പര്യവേക്ഷണം വീണ്ടും ε = {e} ആയി. ഇനിയും പഠിപ്പിച്ച് അത് എങ്ങനെ ഇണങ്ങുന്നു എന്ന് കാണൂ.',
  msg_reset: 'പഠനം റീസെറ്റ് ചെയ്തു: എല്ലാ Q-മൂല്യവും വീണ്ടും 0.',
  msg_start_cell: 'ഇത് റോബോട്ടിന്റെ തുടക്ക കളമാണ്. മാറ്റാൻ “തുടക്കം മാറ്റുക” തിരഞ്ഞെടുക്കുക.',
  msg_preset: '“{name}” ലോകം ലോഡ് ചെയ്തു. റോബോട്ട് പൂജ്യത്തിൽ നിന്ന് പഠനം തുടങ്ങും.',
