  preset_empty: 'തുറന്ന മൈതാനം',
  hint_simple: 'കുറച്ച് ചുവരുകളും കുഴികളും. തുടങ്ങാൻ നല്ല ലോകം.',
  hint_maze: 'നീണ്ട, വളഞ്ഞുപുളഞ്ഞ വഴി. ഒരു എളുപ്പവഴി കുഴിയിൽ അവസാനിക്കുന്നു!',
  hint_cliff: 'താഴത്തെ വരി നിറയെ കുഴികൾ. ഏറ്റവും ചെറിയ വഴി അരികിനോട് ചേർന്നാണ് പോകുന്നത്.',
  hint_empty: 'ചുവരില്ല, കുഴിയില്ല. മൂല്യങ്ങൾ നിധിയിൽ നിന്ന് ചുറ്റും പരക്കുന്നത് കാണൂ.',
  hint_custom: 'നിങ്ങളുടെ സ്വന്തം ലോകം. കളങ്ങളിൽ തൊട്ട് മാറ്റുക.',
