  hint_cycle: 'ഓരോ തൊടലിലും: ശൂന്യം → ചുവർ → കുഴി → നിധി → ശൂന്യം. പല കളങ്ങൾക്കും വിരൽ വലിക്കുക.',
  hint_start: 'തൊടുന്ന കളത്തിൽ നിന്ന് റോബോട്ട് തുടങ്ങും.',
  hint_look: 'ഒരു കളത്തിൽ തൊട്ട്, “റോബോട്ടിന്റെ തലച്ചോറിനുള്ളിൽ” അതിന്റെ 4 Q-മൂല്യങ്ങൾ കാണുക.',
