  eps_hint: 'ക്രമരഹിത നീക്കത്തിനുള്ള സാധ്യത. ക്രമരഹിത നീക്കങ്ങൾ പുതിയ വഴികൾ കണ്ടെത്തുന്നു; നല്ല നീക്കങ്ങൾ അറിയാവുന്നത് ഉപയോഗിക്കുന്നു.',
