  chart_empty: 'റോബോട്ടിനെ പഠിപ്പിക്കൂ, അതിന്റെ സമ്മാനങ്ങൾ ഇവിടെ കാണാം.',
  chart_note: 'ആദ്യം രേഖ താഴെയും കയറ്റിറക്കങ്ങളോടെയും ആയിരിക്കും: റോബോട്ട് പര്യവേക്ഷണം ചെയ്ത് കുഴികളിൽ വീഴുന്നു. പഠിക്കുന്തോറും രേഖ സാധ്യമായ ഏറ്റവും മികച്ച സമ്മാനത്തിലേക്ക് കയറുന്നു.',
