  brain_wall: 'ഇതൊരു ചുവരാണ്. റോബോട്ടിന് ഇവിടെ ഒരിക്കലും നിൽക്കാനാവില്ല.',
  brain_end: 'റോബോട്ട് ഈ കളത്തിൽ കയറിയാലുടൻ എപ്പിസോഡ് തീരും, അതിനാൽ ഇതിന് Q-മൂല്യങ്ങൾ വേണ്ട.',
  upd_title: 'അവസാന അപ്ഡേറ്റ്: Q-ലേണിങ് നിയമം',
  upd_rule: 'പുതിയ Q = പഴയ Q + α × (സമ്മാനം + γ × അടുത്ത കളത്തിലെ മികച്ച Q − പഴയ Q)',
  upd_none: 'ഒരു അപ്ഡേറ്റിന്റെ കണക്ക് കാണാൻ 1 ചുവട് അമർത്തുക.',
  upd_move: 'റോബോട്ട് {from}-ൽ ആയിരുന്നു. അത് {act} തിരഞ്ഞെടുത്തു ({why}), {to}-ൽ എത്തി. സമ്മാനം: {r}.',
  upd_bump: 'റോബോട്ട് {from}-ൽ ആയിരുന്നു. അത് {act} തിരഞ്ഞെടുത്തു ({why}), പക്ഷേ ഇടിച്ച് അവിടെത്തന്നെ നിന്നു. സമ്മാനം: {r}.',
